package com.unicare.dispensary.message;
import com.unicare.dispensary.student.Student;import jakarta.persistence.*;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;
@Entity @Table(name="dispensary_messages",indexes=@Index(name="idx_message_student",columnList="student_id")) public class DispensaryMessage{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="student_id",nullable=false)private Student student;@Column(nullable=false,length=120)private String subject;@Column(nullable=false,length=2000)private String body;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private MessageStatus status=MessageStatus.OPEN;@Column(nullable=false)private LocalDateTime createdAt;@ElementCollection(fetch=FetchType.LAZY)@CollectionTable(name="message_replies",joinColumns=@JoinColumn(name="message_id"))@OrderColumn(name="reply_order")private List<MessageReply> replies=new ArrayList<>();protected DispensaryMessage(){}public DispensaryMessage(Student student,String subject,String body){this.student=student;this.subject=subject;this.body=body;}@PrePersist void onCreate(){createdAt=LocalDateTime.now();}public Long getId(){return id;}public Student getStudent(){return student;}public String getSubject(){return subject;}public String getBody(){return body;}public MessageStatus getStatus(){return status;}public LocalDateTime getCreatedAt(){return createdAt;}public List<MessageReply> getReplies(){return replies;}public void reply(String author,String body){replies.add(new MessageReply(author,body));status=MessageStatus.REPLIED;}public void close(){status=MessageStatus.CLOSED;}}
